From bbf771b5d27585f29ca0a905645b598c8d2af433 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:16:00 +0100
Subject: [PATCH] klipper: give action popup commands keyboard accelerators

The action popup only gave Cancel an accelerator, so reaching a command
from the keyboard took one arrow press per entry. Let KAcceleratorManager
assign a letter to each command, keeping any the user set with "&".

BUG: 526838
---
 klipper/urlgrabber.cpp | 2 ++
 1 file changed, 2 insertions(+)

diff --git a/klipper/urlgrabber.cpp b/klipper/urlgrabber.cpp
index 90717ade01..4effa58f8f 100644
--- a/klipper/urlgrabber.cpp
+++ b/klipper/urlgrabber.cpp
@@ -18,6 +18,7 @@
 #include <QTimer>
 #include <QUuid>

+#include <KAcceleratorManager>
 #include <KApplicationTrader>
 #include <KIO/ApplicationLauncherJob>
 #include <KLocalizedString>
@@ -215,6 +216,7 @@ void URLGrabber::actionMenu(HistoryItemConstPtr item, bool automatically_invoked

         auto *cancelAction = new QAction(QIcon::fromTheme(QStringLiteral("dialog-cancel")), i18n("&Cancel"), m_myMenu.get());
         m_myMenu->addAction(cancelAction);
+        KAcceleratorManager::manage(m_myMenu.get());
         m_myClipItem = item;

         if (m_myPopupKillTimeout > 0)
-- 
